import React from 'react'

export const Task = () => {
  const tasks = [
    { id: 1, name: 'Task 1', status: 'Completed' },
    { id: 2, name: 'Task 2', status: 'In Progress' },
    { id: 3, name: 'Task 3', status: 'Pending' },
  ];

  return (
    <div>
      <h2>Task List</h2>
      <table border="1">
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {tasks.map((task) => (
            <tr key={task.id}>
              <td>{task.id}</td>
              <td>{task.name}</td>
              <td>{task.status}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default Task;
